<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function gs_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())gs_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))gs_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$role=(string)$_SESSION['role'];$writers=['director','sub_director','headteacher'];$readerRoles=['director','sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher'];if(!in_array($role,$readerRoles,true))gs_json(403,['ok'=>false,'message'=>'Your role cannot access grading scales.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)gs_json(422,['ok'=>false,'message'=>'Choose a school.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())gs_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
if($_SERVER['REQUEST_METHOD']==='GET'){$year=filter_var($_GET['academic_year']??null,FILTER_VALIDATE_INT);if(!$year||$year<2000||$year>2100)gs_json(422,['ok'=>false,'message'=>'Choose a valid academic year.']);$q=$db->prepare("SELECT g.id,g.name,g.academic_year,g.class_id,c.name class_name,g.status,g.published_at,b.label,b.minimum_percent,b.maximum_percent,b.comment FROM school_grading_scales g LEFT JOIN school_classes c ON c.id=g.class_id AND c.school_id=g.school_id LEFT JOIN school_grading_bands b ON b.scale_id=g.id WHERE g.school_id=? AND g.academic_year=? AND (g.status='published' OR ?=1) ORDER BY g.created_at DESC,b.sort_order,b.minimum_percent" );$q->execute([$school,$year,in_array($role,$writers,true)?1:0]);gs_json(200,['ok'=>true,'data'=>['scales'=>$q->fetchAll()]]);}
if($_SERVER['REQUEST_METHOD']!=='POST')gs_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!in_array($role,$writers,true))gs_json(403,['ok'=>false,'message'=>'Only school leadership can manage grading scales.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))gs_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
try{if($action==='create'){$name=trim((string)($_POST['name']??''));$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);$class=($_POST['class_id']??'')===''?null:filter_var($_POST['class_id'],FILTER_VALIDATE_INT);$bands=json_decode((string)($_POST['bands']??''),true,512,JSON_THROW_ON_ERROR);if($name===''||mb_strlen($name)>120||!$year||$year<2000||$year>2100||($class!==null&&(!$class||$class<1))||!is_array($bands)||count($bands)<1||count($bands)>30)throw new DomainException('Enter a scale name, year, optional class, and 1–30 grade bands.');if($class!==null){$q=$db->prepare('SELECT 1 FROM school_classes WHERE id=? AND school_id=?');$q->execute([$class,$school]);if(!$q->fetchColumn())throw new DomainException('That class is outside this school.');}$clean=[];$labels=[];foreach($bands as $i=>$b){if(!is_array($b))throw new DomainException('Each grade band must include a label and percentage range.');$label=trim((string)($b['label']??''));$min=filter_var($b['minimum_percent']??null,FILTER_VALIDATE_FLOAT);$max=filter_var($b['maximum_percent']??null,FILTER_VALIDATE_FLOAT);$comment=trim((string)($b['comment']??''));if($label===''||mb_strlen($label)>40||isset($labels[mb_strtolower($label)])||$min===false||$max===false||$min<0||$max>100||$min>$max||mb_strlen($comment)>180)throw new DomainException('Use unique labels and valid 0–100 percentage ranges for every band.');$labels[mb_strtolower($label)]=true;$clean[]=['label'=>$label,'min'=>(float)$min,'max'=>(float)$max,'comment'=>$comment?:null,'order'=>$i];}usort($clean,fn($a,$b)=>$a['min']<=>$b['min']);for($i=1;$i<count($clean);$i++)if($clean[$i]['min']<=$clean[$i-1]['max'])throw new DomainException('Grade band ranges cannot overlap.');$db->beginTransaction();$q=$db->prepare("INSERT INTO school_grading_scales(school_id,name,academic_year,class_id,status,created_by) VALUES(?,?,?,?,'draft',?)");$q->execute([$school,$name,$year,$class,$uid]);$id=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO school_grading_bands(scale_id,label,minimum_percent,maximum_percent,comment,sort_order) VALUES(?,?,?,?,?,?)');foreach($clean as $b)$q->execute([$id,$b['label'],$b['min'],$b['max'],$b['comment'],$b['order']]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'create','school_grading_scale',$id,json_encode(['school_id'=>$school,'academic_year'=>$year,'class_id'=>$class,'bands'=>count($clean)],JSON_THROW_ON_ERROR)]);$db->commit();gs_json(200,['ok'=>true,'message'=>'Grading scale draft saved.','data'=>['id'=>$id]]);}
if($action==='publish'){$id=(int)($_POST['scale_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id,status FROM school_grading_scales WHERE id=? AND school_id=? FOR UPDATE");$q->execute([$id,$school]);$scale=$q->fetch();if(!$scale||$scale['status']!=='draft')throw new DomainException('Only a draft scale in this school can be published.');$q=$db->prepare('SELECT COUNT(*),MIN(minimum_percent),MAX(maximum_percent) FROM school_grading_bands WHERE scale_id=?');$q->execute([$id]);$range=$q->fetch(PDO::FETCH_NUM);if((int)$range[0]<1)throw new DomainException('Add at least one grade band before publishing.');$q=$db->prepare('SELECT minimum_percent,maximum_percent FROM school_grading_bands WHERE scale_id=? ORDER BY minimum_percent');$q->execute([$id]);$prev=null;foreach($q->fetchAll() as $b){if($prev!==null&&(float)$b['minimum_percent']<=(float)$prev)throw new DomainException('Grade band ranges cannot overlap.');$prev=$b['maximum_percent'];}$db->prepare("UPDATE school_grading_scales SET status='published',published_by=?,published_at=CURRENT_TIMESTAMP WHERE id=? AND school_id=? AND status='draft'")->execute([$uid,$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'publish','school_grading_scale',$id,json_encode(['school_id'=>$school],JSON_THROW_ON_ERROR)]);$db->commit();gs_json(200,['ok'=>true,'message'=>'Scale published. Create a new draft for future revisions.']);}throw new DomainException('Choose a supported grading scale action.');}catch(DomainException $e){if($db->inTransaction())$db->rollBack();gs_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Grading scale request error: '.$e->getMessage());gs_json(500,['ok'=>false,'message'=>'The grading scale request failed. Verify its migration.']);}
